/** Theme appearance mode */
export type ThemeMode = 'light' | 'dark' | 'system';

/** Resolved appearance (never "system") */
export type ResolvedMode = 'light' | 'dark';

/** Contrast algorithm for adaptive text / icons */
export type ContrastAlgorithm = 'WCAG' | 'APCA';

/** Color-blind simulation variants */
export type ColorBlindVariant =
  | 'none'
  | 'protanopia'
  | 'deuteranopia'
  | 'tritanopia';

/** Hex color string (#RGB, #RRGGBB, or #RRGGBBAA) */
export type HexColor = string;

/**
 * Semantic color tokens for a single appearance (light or dark).
 * Generated by `createTheme` from one seed color.
 */
export interface ColorTokens {
  /** App / screen background */
  background: HexColor;
  /** Elevated surface (cards, sheets) */
  surface: HexColor;
  /** Slightly higher elevation than surface */
  surfaceElevated: HexColor;
  /** Brand / primary action color */
  primary: HexColor;
  /** Text/icons on primary */
  onPrimary: HexColor;
  /** Soft primary tint (chips, selected rows) */
  primaryContainer: HexColor;
  /** Text/icons on primaryContainer */
  onPrimaryContainer: HexColor;
  /** Secondary accent */
  secondary: HexColor;
  /** Text/icons on secondary */
  onSecondary: HexColor;
  /** Soft secondary tint */
  secondaryContainer: HexColor;
  /** Text/icons on secondaryContainer */
  onSecondaryContainer: HexColor;
  /** Highest-emphasis body text */
  text: HexColor;
  /** Secondary / supporting text */
  textSecondary: HexColor;
  /** Placeholder / disabled text */
  textMuted: HexColor;
  /** Inverted text (e.g. on inverted surfaces) */
  textInverse: HexColor;
  /** Dividers, outlines, input borders */
  border: HexColor;
  /** Subtle border / hairline */
  borderSubtle: HexColor;
  /** Error / destructive */
  error: HexColor;
  /** Text/icons on error */
  onError: HexColor;
  /** Soft error background */
  errorContainer: HexColor;
  /** Success */
  success: HexColor;
  /** Text/icons on success */
  onSuccess: HexColor;
  /** Soft success background */
  successContainer: HexColor;
  /** Warning */
  warning: HexColor;
  /** Text/icons on warning */
  onWarning: HexColor;
  /** Soft warning background */
  warningContainer: HexColor;
  /** Info */
  info: HexColor;
  /** Text/icons on info */
  onInfo: HexColor;
  /** Soft info background */
  infoContainer: HexColor;
  /** Scrim / modal overlay */
  overlay: HexColor;
  /** Focus ring / outline for a11y */
  focus: HexColor;
  /** Ripple / press feedback */
  ripple: HexColor;
}

/** Optional spacing / radius / typography extensions */
export interface ThemeMetrics {
  radius: {
    sm: number;
    md: number;
    lg: number;
    full: number;
  };
  spacing: {
    xs: number;
    sm: number;
    md: number;
    lg: number;
    xl: number;
    xxl: number;
  };
}

/** Full theme: light + dark palettes from one seed */
export interface Theme {
  /** Original seed / brand color */
  seed: HexColor;
  light: ColorTokens;
  dark: ColorTokens;
  metrics: ThemeMetrics;
  /** Optional metadata */
  meta?: {
    name?: string;
    version?: number;
  };
}

/** Options for `createTheme` */
export interface CreateThemeOptions {
  /** Primary / brand seed color (required) */
  primary: HexColor;
  /** Optional secondary seed; derived from primary if omitted */
  secondary?: HexColor;
  /** Override generated light tokens partially */
  lightOverrides?: Partial<ColorTokens>;
  /** Override generated dark tokens partially */
  darkOverrides?: Partial<ColorTokens>;
  /** Custom metrics */
  metrics?: Partial<ThemeMetrics>;
  /** Theme display name */
  name?: string;
  /**
   * Minimum WCAG contrast ratio for text-on-background pairs.
   * @default 4.5 (AA normal text)
   */
  minContrast?: number;
}

/** Result of image → theme generation */
export interface ImageThemeMeta {
  primary: HexColor;
  secondary?: HexColor;
  swatchCount: number;
}

/** Persistence adapter interface */
export interface ThemeStorage {
  getItem: (key: string) => string | null | Promise<string | null>;
  setItem: (key: string, value: string) => void | Promise<void>;
  removeItem?: (key: string) => void | Promise<void>;
}

/** ThemeProvider props */
export interface ThemeProviderProps {
  /** Theme from `createTheme` (or custom) */
  theme: Theme;
  /** Initial mode before persistence / system resolve */
  defaultMode?: ThemeMode;
  /** Force mode (ignores system + persistence until cleared) */
  forcedMode?: ResolvedMode | null;
  /** Persist user mode preference */
  persist?: boolean;
  /** Storage key for mode preference */
  storageKey?: string;
  /** Custom storage (MMKV / AsyncStorage adapter) */
  storage?: ThemeStorage;
  /** High contrast boost */
  highContrast?: boolean;
  /** Color-blind safe remapping */
  colorBlindVariant?: ColorBlindVariant;
  /** Animate color transitions (requires reanimated) */
  animateTransitions?: boolean;
  /** Transition duration in ms */
  transitionDuration?: number;
  /** Respect system Reduce Motion */
  respectReduceMotion?: boolean;
  children: React.ReactNode;
}

/** Value exposed by `useTheme` */
export interface ThemeContextValue {
  /** Full theme object */
  theme: Theme;
  /** Active color tokens for the resolved mode */
  colors: ColorTokens;
  /** User / provider mode preference (may be "system") */
  mode: ThemeMode;
  /** Actual light or dark in use */
  resolvedMode: ResolvedMode;
  /** Whether appearance is dark */
  isDark: boolean;
  /** Set light / dark / system */
  setMode: (mode: ThemeMode) => void;
  /** Force light or dark until cleared */
  forceMode: (mode: ResolvedMode | null) => void;
  /** Toggle between light and dark (clears system) */
  toggleMode: () => void;
  /** High contrast enabled */
  highContrast: boolean;
  setHighContrast: (enabled: boolean) => void;
  /** Color-blind variant */
  colorBlindVariant: ColorBlindVariant;
  setColorBlindVariant: (variant: ColorBlindVariant) => void;
  /** System Reduce Motion is on */
  reduceMotion: boolean;
  /** Whether theme transitions should animate */
  animateTransitions: boolean;
  /** Transition duration in ms */
  transitionDuration: number;
  /** Metrics (spacing, radius) */
  metrics: ThemeMetrics;
  /** Export theme as JSON string */
  exportTheme: () => string;
  /** Replace theme at runtime */
  importTheme: (jsonOrTheme: string | Theme) => void;
}
